import{_ as t,c as o,o as r,ag as a}from"./chunks/framework.BwVZiZlf.js";const y=JSON.parse('{"title":"Parents Are Also New to This World","description":"","frontmatter":{"date":"2025-04-08T00:00:00.000Z","author":"Vast Life"},"headers":[],"relativePath":"blog/2025/04/08/understanding-our-parents.md","filePath":"blog/2025/04/08/understanding-our-parents.md","lastUpdated":1786674252000}'),n={name:"blog/2025/04/08/understanding-our-parents.md"};function s(i,e,h,d,l,u){return r(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1744070400000"},e[0]||(e[0]=[a('<h1 id="parents-are-also-new-to-this-world" tabindex="-1">Parents Are Also New to This World <a class="header-anchor" href="#parents-are-also-new-to-this-world" aria-label="Permalink to &quot;Parents Are Also New to This World&quot;">​</a></h1><p>In recent years, more and more young people have taken to social media to share stories about their upbringing — about growing up in households where they felt controlled, criticized, emotionally neglected, misunderstood, and silenced.</p><blockquote><p>“My parents never praised me, only put me down.”<br> “I got a 90 on my test, and all they asked was where the other 10 points went.”</p></blockquote><p>These stories resonate deeply with many. Some feel seen, others feel anger and resentment, and some stay silent — especially now that they themselves have become parents, overwhelmed by a mix of emotions.</p><p>Those who carry childhood wounds often say they’ve become people-pleasers, socially anxious, or emotionally insecure. Their pain is real. Their sadness is not imagined. This generation is starting to awaken — to heal, and to say, <em>&quot;I don’t want to pass this on to my children.&quot;</em></p><p>But behind these voices are others who remain quiet.<br> They wear worn-out clothes, bargain at the morning market, count out coins carefully on the bus, and hesitate for minutes over a few dollars on a food delivery app.</p><p>They are our parents.</p><p>What many forget is that on the night we were born, the man pacing nervously in the hospital hallway, rubbing his hands in worry — that was Dad.<br> And the pale-faced woman, fresh from stitches yet still trying to feed us our first drop of milk — that was Mom.</p><p>They too were once in their twenties, stumbling through the unfamiliar role of being “parents.” No one ever taught them how to be good fathers or mothers. So they did the only thing they could — they figured it out as they went, while carrying the weight of raising a child.</p><p>They weren’t experts. They didn’t study psychology. They didn’t learn about “non-violent communication” or “emotional support.”<br> They just knew: if the child is hungry, feed them; if they cry, soothe them; if they’re sick, drop everything and run to the hospital.</p><p>They worked long hours, took on extra shifts, and lived under the crushing pressure of responsibility.<br> And when they lost their temper and said harsh things or even raised a hand — it wasn’t because they didn’t love us. It was because their love was clumsy, unpolished, and sometimes... painfully imperfect.</p><p>When we were hurt, they were hurting too.</p><p>They were never superheroes. They were — and still are — ordinary people, with their own anxieties, frustrations, and fears.<br> While trying to be our parents, they were also worrying about bills, juggling work, and shouldering the burdens of life. They never had the luxury of self-improvement. Life didn’t give them that kind of time or space.</p><p>We say they never understood us — but have we ever wondered if they were ever understood?<br> Their own childhoods may have been just as bruised, but they never had a safe place to talk about it.<br> They didn’t grow up watching bite-sized therapy videos on social media or scrolling through posts that echo their pain. All they knew was to grit their teeth and keep going — for us.</p><p>If we are healing our childhood wounds, perhaps they too are still fumbling their way through healing — only they started later and move more slowly.</p><p>So what does it really mean to grow up?</p><p>It means we begin to recognize our own scars — and gain the courage to see others’ struggles too.<br> It means we can say, “I was hurt as a child,” and also say, “I know you did your best.”<br> We have every right to mourn our childhood, and still shed tears for the hardships our parents endured.</p><p>Our generation is luckier.<br> We have access to better resources, a more open environment, and a stronger sense of self-awareness.</p><p>May we all learn to let go through understanding, and grow through compassion.</p>',19)]))}const g=t(n,[["render",s]]);export{y as __pageData,g as default};
